import assert from 'node:assert/strict';
import type { TranscriptTurn } from '@gugu/session-core/acp';

/** Generated bytes only. Match the measured image counts/lengths, never private transcript content. */
export function payloadConversation(): TranscriptTurn[] {
  const copies = [...Array<number>(45).fill(1), ...Array<number>(20).fill(2), ...Array<number>(3).fill(3),
    ...Array<number>(2).fill(4), 5, 6, 6];
  const lengths = copies.map(() => 400000);
  lengths[0] += 29644; lengths[45] -= 4; lengths[71] -= 64128;
  const images = copies.map((count, index) => {
    const bytes = Buffer.alloc(lengths[index] * 3 / 4);
    let seed = index + 1;
    for (let at = 0; at < bytes.length; at++) {
      seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5; bytes[at] = seed & 255;
    }
    return { count, data: bytes.toString('base64') };
  });
  assert.equal(images.length, 73);
  assert.equal(images.reduce((sum, image) => sum + image.count, 0), 119);
  assert.equal(images.reduce((sum, image) => sum + image.data.length, 0), 29165512);
  assert.equal(images.reduce((sum, image) => sum + image.data.length * image.count, 0), 47244868);
  const imageId = 'bench:turn:s0', outputId = 'bench:turn:s1';
  const pictures: TranscriptTurn = { id: imageId, referenceId: 'synthetic:images', seq: 0, initiator: 'user', startedAt: 10, endedAt: 20,
    outcome: { kind: 'done' }, items: [{ kind: 'message', id: `${imageId}:message:u`, seq: 0, role: 'user', text: 'Synthetic image turn' }] };
  for (const image of images) for (let at = 0; at < image.count; at++) {
    const seq = pictures.items.length;
    pictures.items.push({ kind: 'mcp-tool-call', id: `${imageId}:tool:${seq}`, seq, toolCallId: `image:${seq}`,
      title: 'Synthetic screenshot', tool: 'screenshot', status: 'done', images: [{ mimeType: 'image/png', data: image.data }] });
  }
  const outputs: TranscriptTurn = { id: outputId, referenceId: 'synthetic:outputs', seq: 1, initiator: 'user', startedAt: 30, endedAt: 40,
    outcome: { kind: 'done' }, items: [{ kind: 'message', id: `${outputId}:message:u`, seq: 0, role: 'user', text: 'Synthetic execute turn' }] };
  const total = 10688334, count = 1277;
  let generated = 0;
  for (let index = 0; index < count; index++) {
    const length = Math.floor(total / count) + Number(index < total % count), bytes = Buffer.alloc(length);
    let seed = 0x12345678 ^ (index + 1);
    for (let at = 0; at < length; at++) {
      seed ^= seed << 13; seed ^= seed >>> 17; seed ^= seed << 5;
      bytes[at] = (seed >>> 0) % 20 === 0 ? 10 : 32 + ((seed >>> 0) % 95);
    }
    const text = bytes.toString('ascii'), seq = outputs.items.length;
    generated += Buffer.byteLength(text);
    outputs.items.push({ kind: 'execute-tool-call', id: `${outputId}:tool:${seq}`, seq, toolCallId: `execute:${seq}`,
      title: 'Synthetic execute', status: 'done', outputText: text, rawOutput: JSON.stringify({ aggregatedOutput: text, exitCode: 0 }, null, 2) });
  }
  assert.equal(generated, total);
  return [pictures, outputs];
}
